import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, map } from 'rxjs';

// The signed-in user. Sign-in is by name only (no password); the name is sent on every API call
// in the X-User header.
@Injectable({ providedIn: 'root' })
export class SessionService {
  private readonly http = inject(HttpClient);
  private readonly name = signal<string | null>(null);

  readonly user = this.name.asReadonly();

  signIn(name: string): Observable<string> {
    return this.http
      .post<{ name: string }>('/api/session', { name })
      .pipe(map((s) => (this.name.set(s.name), s.name)));
  }

  headers(): Record<string, string> {
    const user = this.name();
    return user ? { 'X-User': user } : {};
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, map } from 'rxjs';
import { SessionService } from './session.service';

// The active sheet. Everything else in the app is kept per sheet; loading an id re-reads it from
// the store (a sheet never loaded before starts empty).
@Injectable({ providedIn: 'root' })
export class SheetService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly current = signal<string | null>(null);

  readonly sheetId = this.current.asReadonly();

  load(id: string): Observable<string> {
    return this.http
      .post<{ id: string }>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
        headers: this.session.headers(),
      })
      .pipe(map((s) => (this.current.set(s.id), s.id)));
  }
}
import { Component, inject } from '@angular/core';
import { SessionService } from '../../core/session.service';
import { SheetPicker } from '../session/sheet-picker';
import { SignIn } from '../session/signin';

// The one screen: sign in, then choose a sheet.
@Component({
  selector: 'app-home',
  imports: [SignIn, SheetPicker],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <span data-testid="current-user">{{ user }}</span></p>
      <app-sheet-picker />
    } @else {
      <app-signin />
    }
  `,
})
export class Home {
  protected readonly session = inject(SessionService);
}
import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { SheetService } from '../../core/sheet.service';

// Choose the active sheet by typing its id and loading it.
@Component({
  selector: 'app-sheet-picker',
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Load sheet">
      <label for="sheet-id-input">Sheet id</label>
      <input id="sheet-id-input" data-testid="sheet-id-input" formControlName="id" />
      <button type="submit" data-testid="sheet-load">Load</button>
      @if (error()) {
        <p role="alert" data-testid="sheet-error">{{ error() }}</p>
      }
    </form>
    @if (sheets.sheetId(); as current) {
      <p>Sheet: <span data-testid="sheet-current-id">{{ current }}</span></p>
    }
  `,
})
export class SheetPicker {
  protected readonly sheets = inject(SheetService);
  protected readonly form = new FormGroup({ id: new FormControl('', { nonNullable: true }) });
  protected readonly error = signal('');

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  protected submit(): void {
    this.error.set('');
    const id = this.form.controls.id.value.trim();
    if (!/^[A-Za-z0-9_-]{1,100}$/.test(id)) {
      this.error.set('Enter a sheet id (letters, digits, - or _).');
      return;
    }
    this.sheets.load(id).subscribe({ error: () => this.error.set('Could not load that sheet.') });
  }
}
import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { SessionService } from '../../core/session.service';

// Sign in by typing a name.
@Component({
  selector: 'app-signin',
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Sign in">
      <label for="signin-name">Name</label>
      <input id="signin-name" data-testid="signin-name" formControlName="name" autocomplete="username" />
      <button type="submit" data-testid="signin-submit">Sign in</button>
      @if (error()) {
        <p role="alert" data-testid="signin-error">{{ error() }}</p>
      }
    </form>
  `,
})
export class SignIn {
  private readonly session = inject(SessionService);
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true, validators: Validators.required }),
  });
  protected readonly error = signal('');

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
